{"command":"python3 -c "
import json, os
# List all skill dirs
skills_dir = '/data/.hermes/skills'
for item in sorted(os.listdir(skills_dir)):
    path = os.path.join(skills_dir, item)
    if os.path.isdir(path) and not item.startswith('.'):
        refs = os.path.exists(os.path.join(path, 'references'))
        scripts = os.path.exists(os.path.join(path, 'scripts'))
        sub_skills = []
        for sub in os.listdir(path):
            sub_path = os.path.join(path, sub)
            if os.path.isdir(sub_path) and not sub.startswith('.'):
                sub_skill_md = os.path.join(sub_path, 'SKILL.md')
                if os.path.exists(sub_skill_md):
                    sub_skills.append(sub)
                # Check for nested
                for nested in os.listdir(sub_path):
                    nested_path = os.path.join(sub_path, nested)
                    if os.path.isdir(nested_path) and not nested.startswith('.'):
                        nested_skill = os.path.join(nested_path, 'SKILL.md')
                        if os.path.exists(nested_skill):
                            sub_skills.append(f'{sub}/{nested}')
        print(f'{item} | refs={refs} scripts={scripts} sub_skills={sub_skills}')
""}

