import json, os
cron_dir = '/data/.hermes/cron'
for f in os.listdir(cron_dir):
    if f.endswith('.json'):
        with open(os.path.join(cron_dir, f)) as fh:
            data = json.load(fh)
        skills = data.get('skills', [])
        name = data.get('name', f)
        if skills:
            print(f'{name} ({f}): skills={skills}')
        else:
            print(f'{name} ({f}): no skills')
""}

